}
&amp;plan.Sort{
    UnaryNode: plan.UnaryNode{
        Child: &amp;plan.Having{
            UnaryNode: plan.UnaryNode{
                Child: &amp;plan.GroupBy{
                    UnaryNode: plan.UnaryNode{
                        Child: &amp;plan.LeftJoin{
