                                                                name:     "country",
                                                                Database: "",
                                                                AsOf:     nil,
                                                            },
                                                            right: &amp;plan.UnresolvedTable{
                                                                name:     "city",
                                                                Database: "",
                                                                AsOf:     nil,
                                                            },
                                                        },
